  // staff focus must use the exact realm color, not the generic armor shade.
  for(const part of [rig.sternum,rig.staffFocus,rig.staffFocusAura]){if(part?.material?.color){part.material.color.setHex(palette.glow);if(part.material.emissive){part.material.emissive.setHex(palette.glow);part.material.emissiveIntensity=2.8}part.userData.liveColor=part.material.color.clone();part.userData.liveEmissive=part.material.emissive?.clone()||null;part.userData.liveEmissiveIntensity=part.material.emissiveIntensity||0}}
