    const expected=m.nodes.find(node=>!node.done),nearby=m.nodes.find(node=>!node.done&&near(node));if(!nearby)return false;if(nearby!==expected){toast(`SEALED ROUTE · FIND ${expected.label.toUpperCase()}`);return true}if(nearby.kind==='root'){toast('CORRUPTED ROOT · EQUIP THE SWORD AND CUT IT 3 TIMES');return true}const alive=missionEnemiesAlive();if(alive.length){toast(`CHAMBER UNSAFE · ${alive.length} GUARDIAN${alive.length===1?'':'S'} REMAIN`);return true}finishExpeditionNode(expected);return true
