    const hostilesAlive=state.bots.some(bot=>bot.userData.hp>0&&!bot.userData.down)||state.drones.some(drone=>!drone.destroyed&&drone.hp>0),helpersAlive=state.helpers.some(helper=>helper.userData.hp>0&&!helper.userData.down),playerAlive=!state.simulationSpectator&&!state.defeated;
