    if(!helpersAlive&&!playerAlive){showMatchResult('HOSTILES WIN','The simulated opposition eliminated the helper team.',{outcome:'defeat',eyebrow:'SIMULATION COMPLETE',actionLabel:'RETURN HOME',allowView:true});return true}
