function aim(){return new THREE.Vector3(0,0,-1).applyEuler(new THREE.Euler(state.pitch,state.yaw,0,'YXZ')).normalize()}
function cast(spell,remoteOrigin=null,remoteDirection=null,remoteTargetId=null){
  if(!remoteOrigin&&state.earthMode){toast('ARCANE SYSTEMS ARE INERT ON EARTH');return}
  if(!remoteOrigin&&spell==='sword'&&performance.now()<state.nextSwordSwing)return;
  if(!remoteOrigin&&!canCast(spell)){if(spell==='blast'&&state.cooldowns.blast>performance.now())toast(`BLAST RECHARGING · ${Math.ceil((state.cooldowns.blast-performance.now())/1000)}s`);return}
  const origin=remoteOrigin?new THREE.Vector3(remoteOrigin.x,remoteOrigin.y,remoteOrigin.z):player.position.clone().add(new THREE.Vector3(0,-PLAYER_HAND_DROP,0));
  const lockedSwoopTarget=!remoteOrigin&&spell==='sword'&&performance.now()<state.jetpackSwoopUntil&&state.jetpackSwoopTarget?.userData?.hp>0?state.jetpackSwoopTarget:null,dir=remoteDirection?new THREE.Vector3(remoteDirection.x,remoteDirection.y,remoteDirection.z):lockedSwoopTarget?combatPoint(lockedSwoopTarget,new THREE.Vector3()).sub(origin).normalize():aim();
  const lightningTarget=spell==='lightning'?(remoteOrigin?(String(remoteTargetId)===String(state.id)?player:state.remotes.get(String(remoteTargetId))||state.bots[Number(remoteTargetId)]):acquireCursorTarget()):null;if(spell==='lightning'&&!lightningTarget){if(!remoteOrigin)toast('AIM AT AN ENEMY');return}
  if(!remoteOrigin){if(spell==='sword')state.nextSwordSwing=performance.now()+(state.abilitiesEnhanced?380:450);playFirstPersonAction(spell);if(spellCooldown(spell))cooldown(spell);net({type:'cast',spell,origin,direction:dir,targetId:lightningTarget?.userData?.id??(lightningTarget?state.bots.indexOf(lightningTarget):null),power:playerAttackMultiplier()})}
  const pvpFireball=!remoteOrigin&&spell==='fireball'&&!state.campaign&&!state.simulation,aimedTarget=!remoteOrigin&&spell==='fireball'?acquireAimTarget(pvpFireball?.58:.15,pvpFireball?115:70):null;
  if(spell==='fireball'){const projectile=spawnProjectile('fireball',origin,dir,26,remoteOrigin?24:playerAttackDamage(24),ATTACK_COLORS.player.fire,remoteOrigin?'remote':'local',aimedTarget);if(projectile&&pvpFireball)projectile.trackingStrength=9.5}
  if(spell==='missiles'){const shots=!remoteOrigin&&state.abilitiesEnhanced?9:6,center=(shots-1)/2;for(let i=0;i<shots;i++)stageTimeout(()=>{const local=!remoteOrigin;if(local&&state.simulationSpectator)return;const launchOrigin=local?player.position.clone().add(new THREE.Vector3((i-center)*.15,-PLAYER_HAND_DROP,0)):origin.clone().add(new THREE.Vector3((i-center)*.18,.1,0)),launchDirection=local?aim():dir.clone();launchDirection.applyAxisAngle(new THREE.Vector3(0,1,0),(i-center)*.03);const projectile=spawnProjectile('missile',launchOrigin,launchDirection,31,local?playerAttackDamage(12):12,ATTACK_COLORS.player.missile,local?'local':'remote');if(projectile)projectile.steerWithAim=local},i*70)}
  if(spell==='lightning')lightningCell(lightningTarget,!remoteOrigin,origin,remoteOrigin?'Ally':'You','player');
  if(spell==='fog')fogArea(origin.clone().addScaledVector(dir,10),'player');
  if(spell==='quake')remoteOrigin?quakeImpact(origin,'remote'):quakeSmash(null);
  if(spell==='blast'){const blastOrigin=remoteOrigin?origin:null;stageTimeout(()=>blastSuper(blastOrigin,remoteOrigin?'remote':'local'),260)}
  if(spell==='sword'){if(remoteOrigin)swordStrike(origin,dir,hasWorldAuthority());else stageTimeout(()=>swordStrike(origin,dir,true),96)}
}
function remoteCast(spell,from,o,d,targetId){if(!['fireball','missiles','lightning','fog','quake','sword','blast'].includes(spell))return;playMageAction(from,spell==='blast'?'quake':spell,spell==='lightning'?950:spell==='blast'?1100:700);cast(spell,o,d,targetId)}

