  const blade=new THREE.Mesh(new THREE.BoxGeometry(.22,.055,1.48),bladeMaterial);blade.position.z=1.2;blade.castShadow=!firstPerson;sword.add(blade);const tip=new THREE.Mesh(new THREE.ConeGeometry(.155,.44,4),bladeMaterial);tip.rotation.x=Math.PI/2;tip.rotation.y=Math.PI/4;tip.position.z=2.16;tip.castShadow=!firstPerson;sword.add(tip);
  const fuller=new THREE.Mesh(new THREE.BoxGeometry(.035,.064,1.23),edgeMaterial);fuller.position.set(0,-.004,1.16);sword.add(fuller);const guard=new THREE.Mesh(new THREE.BoxGeometry(.82,.11,.13),guardMaterial);guard.position.z=.4;guard.castShadow=!firstPerson;sword.add(guard);for(const sideSign of [-1,1]){const quillon=new THREE.Mesh(new THREE.ConeGeometry(.075,.26,6),guardMaterial);quillon.position.set(sideSign*.48,0,.4);quillon.rotation.z=sideSign*Math.PI/2;sword.add(quillon)}
  const grip=new THREE.Mesh(new THREE.CylinderGeometry(.07,.085,.56,10),gripMaterial);grip.rotation.x=Math.PI/2;grip.position.z=.06;sword.add(grip);for(let i=0;i<4;i++){const wrap=new THREE.Mesh(new THREE.TorusGeometry(.083,.012,5,10),guardMaterial);wrap.position.z=-.15+i*.13;sword.add(wrap)}const pommel=new THREE.Mesh(new THREE.DodecahedronGeometry(.12,0),guardMaterial);pommel.position.z=-.28;sword.add(pommel);sword.traverse(object=>{if(object.isMesh)object.renderOrder=firstPerson?1002:0});return sword;
