function finishEarthInfiltration(route,cinematicComplete=false){const score=earthQuestScore(),intel=state.earthQuests?.intel||0;if(route==='helicopter'&&!cinematicComplete){beginHelicopterExtraction();return}state.campaignSaveComplete=true;clearCampaignSave();if(route==='helicopter'){showMatchResult('STYLISH WAY',`You stole the command helicopter and vanished over the perimeter alone. ${score>=5?'The base was left dismantled and its secrets came with you.':'The network is dark; unfinished operations remain below.'}`,{eyebrow:'ROOFTOP EXTRACTION · OPTIONALS '+score+'/6',actionLabel:'RETURN TO FROSTBOUND'});return}if(score>=4)showMatchResult('INVESTIGATOR',`You escaped through the culvert after dismantling the network and completing ${score} optional operations. ${intel===3?'The recovered evidence exposes the full human deployment program.':'Enough evidence survived to begin exposing the program.'}`,{eyebrow:'DEEP INFILTRATION ENDING',actionLabel:'RETURN TO FROSTBOUND'});else showMatchResult('SIMPLE WAY',`You slipped back through the culvert with the deployment network dark. ${score?`${score} optional operation${score===1?'':'s'} completed along the way.`:'Clean, quiet, and unfinished.'}`,{eyebrow:'CLEAN EXTRACTION ENDING',actionLabel:'RETURN TO FROSTBOUND'})}
