  if(state.particles.length>=PERFORMANCE_BUDGET.particles)return;
  const forward=direction.clone().normalize(),side=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0));if(side.lengthSq()<.01)side.set(1,0,0);side.normalize();const up=new THREE.Vector3().crossVectors(side,forward).normalize(),sword=makeSwordModel(false);
