function createFreshRift(mode,map='frost'){state.roomMode=mode;state.selectedMap=map;state.roomArena=map;state.roomCode=createRoomCode();state.creatingRoom=true;ui.roomCode.value=state.roomCode;ui.landingRoomCode.value='';syncRoomLobby();return state.roomCode}
function reserveCreatedRift(){return new Promise((resolve,reject)=>{let settled=false,joined=false;const socket=new WebSocket(relayEndpoint()),finish=(callback,value,keepOpen=false)=>{if(settled)return;settled=true;clearTimeout(timer);if(!keepOpen)socket.close();callback(value)},timer=setTimeout(()=>finish(reject,new Error('ROOM REGISTRATION TIMED OUT')),6000);socket.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.type==='welcome'&&!joined){socket.__riftId=data.id;state.id=data.id;joined=true;socket.send(JSON.stringify(roomJoinPayload(true)));return}if(data.type==='join-error')finish(reject,new Error(data.reason||'ROOM REGISTRATION FAILED'));if(data.type==='room-state'&&data.room===state.roomCode){state.pendingSocket=socket;state.roomHostId=data.hostId||data.id||state.id;state.roomCount=Math.max(1,Number(data.count)||1);state.creatingRoom=false;finish(resolve,data,true)}}catch{}};socket.onerror=()=>finish(reject,new Error('RELAY OFFLINE'));socket.onclose=()=>{if(!settled)finish(reject,new Error('RELAY CLOSED'))}})}
async function publishCreatedRift(button,label){if(!state.creatingRoom)return true;button.disabled=true;ui.landingRoomNote.textContent=label;ui.roomNote.textContent=label;try{await reserveCreatedRift();return true}catch(error){state.pendingSocket?.close();state.pendingSocket=null;state.roomCode='';state.creatingRoom=false;ui.roomCode.value='';syncRoomLobby();toast(error.message||'RIFT REGISTRATION FAILED');return false}finally{button.disabled=false}}
function resolveRift(code){return new Promise((resolve,reject)=>{let settled=false,attempts=0,retryTimer=null;const socket=new WebSocket(relayEndpoint()),lookup=()=>{if(!settled&&socket.readyState===WebSocket.OPEN){attempts++;socket.send(JSON.stringify({type:'lookup-room',room:code}))}},finish=(callback,value,keepOpen=false)=>{if(settled)return;settled=true;clearTimeout(timer);clearTimeout(retryTimer);if(!keepOpen)socket.close();callback(value)},timer=setTimeout(()=>finish(reject,new Error(`RIFT NOT FOUND ON ${location.host} · HOST MUST ENTER FIRST`)),8000);socket.onopen=lookup;socket.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.type==='welcome'){socket.__riftId=data.id;return}if(data.type==='room-info'){state.pendingSocket=socket;finish(resolve,data,true)}else if(data.type==='room-missing'&&attempts<18)retryTimer=setTimeout(lookup,400)}catch{}};socket.onerror=()=>finish(reject,new Error(`RELAY OFFLINE AT ${location.host}`));socket.onclose=()=>{if(!settled)finish(reject,new Error('RELAY CLOSED'))}})}
