function shiftForTabPause(delta){if(delta<=0)return;for(const key of ['lastDamageAt','nextHealthRegen','damageInvulnerableUntil','lastStandReady','blastShieldUntil','blastDamageUntil','blastSpeedUntil','jetpackUntil','jetpackCooldownUntil','jetpackSwoopStarted','jetpackSwoopUntil','shieldBrokenUntil','imprisonedUntil','lightningTickAt','playerKnockbackUntil','nextSwordSwing','phaseEnds','nextDroneShot','nextLightningStrike','earthGraceUntil','earthAlarmUntil','demoStart'])if(Number.isFinite(state[key])&&state[key]>0)state[key]+=delta;if(music.pvpRiseStarted>0)music.pvpRiseStarted+=delta;if(state.countdownEnds>0)state.countdownEnds+=delta;for(const spell of Object.keys(state.cooldowns))state.cooldowns[spell]+=delta;for(const timer of state.stageTimers)timer.due+=delta;if(state.threat?.expires)state.threat.expires+=delta;if(state.earthExtraction?.start)state.earthExtraction.start+=delta;for(const crystal of state.crystals)if(crystal.nextTeleport)crystal.nextTeleport+=delta;for(const actor of [...state.bots,...state.helpers,...state.remotes.values()])for(const key of ['nextSense','nextDecision','nextFlee','fleeUntil','shieldReady','shieldBrokenUntil','nextDefenseFog','nextHealthRegen','lastDamageAt','imprisonedUntil','lightningTickAt','deathStarted','deathUntil','lastSeenAt','staggerUntil'])if(Number.isFinite(actor.userData[key])&&actor.userData[key]>0)actor.userData[key]+=delta}
