const spellOrder=SPELL_ORDER,hotbarButtons=[...document.querySelectorAll('.hotbar button[data-spell]')],blastButton=document.querySelector('[data-super="blast"]'),blastCooldownValue=blastButton.querySelector('.cooldown-value'),jetpackButton=document.querySelector('[data-action="jetpack"]');
