let lastWheelSwitch=0;addEventListener('wheel',e=>{if(!state.started||state.earthMode||state.simulationSpectator||!ui.instructions.classList.contains('hidden')||!e.deltaY)return;e.preventDefault();const now=performance.now();if(now-lastWheelSwitch<24)return;lastWheelSwitch=now;const current=spellOrder.indexOf(state.selectedSpell),step=e.deltaY>0?1:-1;selectSpell(spellOrder[(current+step+spellOrder.length)%spellOrder.length])},{passive:false});
addEventListener('keydown',e=>{unlockAudio();if(e.code==='KeyM'&&!e.repeat){sound.muted=!sound.muted;if(sound.master)sound.master.gain.setTargetAtTime(sound.muted?0:.42,sound.ctx.currentTime,.02);if(sound.muted)music.element?.pause();else playMusic();toast(sound.muted?'SOUND MUTED':'SOUND ENABLED');return}state.keys[e.code]=true;if(e.code==='Space')e.preventDefault();if(e.repeat)return;if(e.code==='KeyR'&&togglePvpReady()){e.preventDefault();return}if(e.code==='KeyV'){activateJetpack();return}if(e.code==='KeyT'){if(!interactMission())pickupDebris();return}if(e.code==='KeyZ'){cast('blast');return}if(state.earthMode&&e.code==='KeyE'){interactEarth();return}if(state.earthMode&&e.code==='KeyR'){reloadRifle();return}if(e.code==='KeyS'&&jetpackActive()){startJetpackSwoop();return}if(e.code==='Space'&&state.started&&playerMovementReady()&&!jetpackActive()&&state.grounded&&!state.imprisoned&&!state.crouched&&!earthVentAt(player.position)){state.velocity.y=9.5;state.grounded=false;return}if(state.earthMode)return;const spells={Digit1:'fireball',Digit2:'missiles',Digit3:'lightning',Digit4:'fog',Digit5:'quake',Digit6:'sword',KeyQ:'quake',KeyF:'fog',KeyC:'lightning',KeyE:'fireball',KeyR:'sword',KeyX:'missiles'};if(spells[e.code])selectSpell(spells[e.code])});
