function animate(time){requestAnimationFrame(animate);if(document.hidden||state.tabSuspended)return;const dt=Math.min(clock.getDelta(),.04);if(state.demo)updateDuel(dt,time);else if(state.started)update(dt,time);else{camera.position.x=Math.cos(time*.00008)*48;camera.position.z=Math.sin(time*.00008)*48;camera.lookAt(0,4,0)}updateBlastCooldown(time);updateMusic();if(state.started){renderedFrames++;const shadowInterval=state.simulation?180:30;if(renderer.shadowMap.enabled&&renderedFrames%shadowInterval===0)renderer.shadowMap.needsUpdate=true}renderPlayerView();perfFrames++;if(time-perfWindow>2500){const fps=perfFrames*1000/(time-perfWindow);if(fps<55&&renderer.getPixelRatio()>.55){renderer.setPixelRatio(Math.max(.55,renderer.getPixelRatio()-.1));renderer.setSize(innerWidth,innerHeight)}perfFrames=0;perfWindow=time}}animate(0);
